import {mountFulfillment,fulfillmentReady,fulfillmentLabel} from './fulfillment.js?v=shipping-17';
import {getPrinter,navigationURL} from './printers.js?v=printer-cards-2';
const query=new URLSearchParams(location.search),orders=window.PopomoOrders,main=document.querySelector('#checkout-main'),footer=document.querySelector('#checkout-footer');let lang='en',order=orders.get(query.get('order')),busy=false,consent=false,filter='all',search='';
try{lang=localStorage.getItem('popomo-language')==='zh'?'zh':'en';}catch{}
const t=(zh,en)=>lang==='en'?en:zh,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=c=>'$'+(c/100).toFixed(2),amount=o=>money(orders.total(o)),date=value=>value?new Date(value).toLocaleString(lang==='en'?'en-US':'zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'—',detailURL=o=>'./checkout.html?view=detail&order='+encodeURIComponent(o.id);
const settled=o=>['paid','printed'].includes(o.status);
const badge=o=>`<span class="checkout-order-status ${settled(o)?'is-paid':''}">${t(o.status==='printed'?'已打印':o.status==='paid'?'已支付':'待支付',o.status==='printed'?'Printed':o.status==='paid'?'Paid':'Awaiting payment')}</span>`;
function fulfillmentTag(item){const method=item.fulfillment?.method,delivery=method==='delivery',known=delivery||method==='pickup';const icon=delivery?'<rect x="4" y="5" width="16" height="15" rx="2"/><path d="M4 10h16M12 5v15"/>':'<rect x="6" y="3" width="12" height="6" rx="1"/><path d="M6 17H4V9h16v8h-2M7 13h10v8H7z"/>';return `<span class="fulfillment-tag ${known?(delivery?'is-delivery':'is-device'):'is-unset'}">${known?`<svg viewBox="0 0 24 24" aria-hidden="true">${icon}</svg>`:''}${fulfillmentLabel(item.fulfillment,lang==='en')}</span>`;}
function row(label,value){return `<div class="order-data-row"><dt>${label}</dt><dd>${value}</dd></div>`;}
function product(){return `<section class="checkout-product"><div class="checkout-cover"><img src="${esc(order.cover)}" alt="${esc(order.name)}"></div><div><h2>${esc(order.name)}</h2><p>${esc(order.model)} · ${order.quantity} ${t('个手机壳','case(s)')}</p></div></section>`;}
function receipt(edit=false){return `<div class="checkout-receipt"><div><span>${t('标准打印','Standard print')} · ${money(order.unitCents)} × ${order.quantity}</span><strong>${money(order.unitCents*order.quantity)}</strong></div>${edit?`<div><span>${t('打印数量','Quantity')}</span><div class="checkout-quantity"><button data-quantity="-1" aria-label="${t('减少数量','Decrease quantity')}" ${order.quantity<=1||busy?'disabled':''}>−</button><output aria-live="polite">${order.quantity}</output><button data-quantity="1" aria-label="${t('增加数量','Increase quantity')}" ${order.quantity>=20||busy?'disabled':''}>＋</button></div></div>`:''}<div><span>${t('图案与文字','Artwork & text')}</span><strong>${t('已包含','Included')}</strong></div><div><span>${t('AI 成本','AI cost')}</span><strong>${money(order.aiCostCents)} <small>${t(!order.aiUsed?'未使用':order.aiCostCents?'':'已包含',!order.aiUsed?'Not used':order.aiCostCents?'':'Included')}</small></strong></div>${order.fulfillment?.method==='delivery'?`<div class="checkout-shipping"><span>${t('快递运费','Shipping')}<small>${t('预计 3–4 天送达','Estimated delivery: 3–4 days')}</small></span><strong>${money(orders.shipping(order))}</strong></div>`:''}<div class="checkout-total"><span>${t(settled(order)?'实付金额':'应付金额',settled(order)?'Amount paid':'Total due')}</span><strong>${amount(order)}</strong></div></div>`;}
function metadata(){return `<section class="order-metadata"><h2>${t('订单信息','Order information')}</h2><dl>${row(t('订单编号','Order number'),esc(order.id))}${row(t('创建时间','Created'),date(order.createdAt))}${row(t('支付时间','Paid at'),date(order.paidAt))}${order.status==='printed'?row(t('打印时间','Printed at'),date(order.printedAt)):''}${row(t('支付方式','Payment method'),order.paymentMethod==='airwallex'?'Airwallex':order.paymentMethod==='online'?t('在线支付','Online payment'):t('待支付','Awaiting payment'))}${row(t('手机型号','Phone model'),esc(order.model))}${row(t('打印数量','Quantity'),order.quantity)}${row(t('领取方式','Fulfillment'),fulfillmentTag(order))}${order.email?row(t('联系邮箱','Contact email'),esc(order.email)):''}</dl></section>`;}
function render(){document.documentElement.lang=lang==='en'?'en':'zh-CN';document.querySelector('#flow-language').value=lang;document.querySelectorAll('[data-zh]').forEach(el=>el.textContent=el.dataset[lang==='en'?'en':'zh']);footer.hidden=true;if(query.get('view')==='orders'){renderOrders();return;}if(!order){main.innerHTML=`<div class="checkout-empty"><h1>${t('未找到订单','Order not found')}</h1><a class="primary" href="./my-designs.html">${t('我的设计','My designs')} ↗</a></div>`;return;}const detail=query.get('view')==='detail'||settled(order);document.title=t(detail?'POPOMO · 订单详情':'POPOMO · 确认与支付',detail?'POPOMO · Order details':'POPOMO · Checkout');main.innerHTML=`<a class="order-back-link" href="./checkout.html?view=orders">← ${t('我的订单','My orders')}</a><div class="checkout-title"><p>${detail?'YOUR LITTLE CREATION, ALL IN ONE PLACE':'ONE LAST LOOK. THEN MAKE IT YOURS.'}</p><div class="order-title-row"><h1>${t(detail?'订单详情':'确认与支付',detail?'Order details':'Review & pay')}</h1>${badge(order)}${fulfillmentTag(order)}</div><span>${t(detail?'查看设计、费用和支付信息。':'付款前，请确认图案和手机型号。',detail?'Your design, costs and payment information.':'Check your artwork and phone model before payment.')}</span></div><div class="checkout-layout">${product()}<div class="order-right-column"><div id="order-fulfillment"></div><section class="checkout-summary"><div class="checkout-order-id"><span>${t('订单编号','Order number')}</span><strong>${esc(order.id)}</strong><small>${t('创建于','Created')} ${date(order.createdAt)}</small></div><h2 class="order-section-title">${t('费用明细','Price breakdown')}</h2>${receipt(!detail)}${!detail?`<form id="payment-form"><label class="order-email-label" for="order-email">${t('联系邮箱（选填）','Contact email (optional)')}</label><input id="order-email" type="email" autocomplete="email" placeholder="you@example.com" value="${esc(order.email||'')}" ${busy?'disabled':''}><div class="checkout-payment-method"><span aria-hidden="true">▭</span><div><strong>Airwallex</strong><small>${t('在线支付','Online payment')}</small></div><i>✓</i></div><label class="order-consent"><input id="payment-consent" type="checkbox" ${consent?'checked':''} ${busy?'disabled':''}><span>${t('我已确认手机型号、图案位置和文字内容。','I have checked my phone model, artwork placement and text.')}</span></label></form>`:''}</section>${detail?metadata():''}</div></div>${detail?`<div class="order-detail-actions">${order.status==='paid'&&order.fulfillment?.method==='pickup'?`<button class="secondary" id="mark-printed">${t('标记为已打印','Mark as printed')}</button>`:''}${order.status==='pending'?`<a class="primary" href="./checkout.html?order=${encodeURIComponent(order.id)}">${t('继续支付','Continue payment')} ${amount(order)} →</a>`:`<a class="primary" href="./my-designs.html">${t('返回我的设计','Back to my designs')} ↗</a>`}<a class="secondary" href="./checkout.html?view=orders">${t('全部订单','All orders')}</a></div>`:''}<p id="checkout-error" role="alert"></p>`;if(!detail){footer.hidden=false;footer.innerHTML=`<a class="checkout-back tertiary" href="./my-designs.html">← ${t('返回作品','Back to designs')}</a><div class="checkout-footer-total"><span>${t('合计','Total')}</span><strong>${amount(order)}</strong></div><button class="primary" id="checkout-next" ${!consent||busy||!fulfillmentReady(order.fulfillment)?'disabled':''}>${busy?`<i class="checkout-spinner"></i> ${t('支付处理中…','Processing…')}`:t('确认支付','Pay now')+' →'}</button>`;bindPayment();}mountFulfillment(document.querySelector('#order-fulfillment'),{value:order.fulfillment,locked:busy,readOnly:settled(order),onSave:(value,{refresh})=>{if(settled(order))return;try{order=orders.update({...order,fulfillment:value});const button=document.querySelector('#checkout-next');if(button)button.disabled=!consent||busy||!fulfillmentReady(value);if(refresh)render();}catch{showError();}}});document.querySelector('#mark-printed')?.addEventListener('click',confirmPrinted);}
function showError(message){document.querySelector('#checkout-error').textContent=message||t('暂时无法保存订单，请重试。','Could not save your order. Please retry.');}
function bindPayment(){const email=document.querySelector('#order-email');email.onchange=()=>{try{order=orders.update({...order,email:email.value.trim()});}catch{showError();}};document.querySelector('#payment-consent').onchange=e=>{consent=e.target.checked;document.querySelector('#checkout-next').disabled=!consent||busy||!fulfillmentReady(order.fulfillment);};main.querySelectorAll('[data-quantity]').forEach(button=>button.onclick=()=>{try{order=orders.update({...order,email:email.value.trim(),quantity:Math.max(1,Math.min(20,order.quantity+Number(button.dataset.quantity)))});render();}catch{showError();}});document.querySelector('#payment-form').onsubmit=e=>e.preventDefault();document.querySelector('#checkout-next').onclick=()=>{if(busy||!consent||!fulfillmentReady(order.fulfillment)||!email.reportValidity())return;try{order=orders.update({...order,email:email.value.trim()});}catch{showError();return;}busy=true;render();setTimeout(()=>{try{order=orders.update({...order,status:'paid',paymentMethod:'airwallex',paidAt:Date.now(),fulfillmentSnapshot:structuredClone({...order.fulfillment,...(order.fulfillment.method==='pickup'?{device:getPrinter(order.fulfillment.deviceId)}:{})})});location.href=detailURL(order)+'&payment=success';}catch{busy=false;render();showError();}},1500);};}
function renderOrders(){document.title=t('POPOMO · 我的订单','POPOMO · My orders');const all=orders.list();main.innerHTML=`<div class="checkout-title orders-title"><p>YOUR PRINT ORDERS</p><h1>${t('我的订单','My orders')}</h1><span>${t('每一份设计，都有自己的记录。','Every creation has a story to keep.')}</span></div><div class="orders-toolbar"><div class="orders-tabs" role="group" aria-label="${t('订单状态','Order status')}">${[['all',t('全部','All')],['pending',t('待支付','Unpaid')],['paid',t('已支付','Paid')],['printed',t('已打印','Printed')]].map(([key,label])=>`<button data-filter="${key}" aria-pressed="${filter===key}">${label} <small>${all.filter(o=>key==='all'||o.status===key).length}</small></button>`).join('')}</div><label class="orders-search"><span aria-hidden="true">⌕</span><input type="search" id="order-search" aria-label="${t('搜索订单编号或作品','Search orders or designs')}" placeholder="${t('搜索订单编号或作品','Search orders or designs')}" value="${esc(search)}"></label></div><section class="checkout-orders" id="orders-results" aria-live="polite"></section>`;renderResults();main.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;renderOrders();});document.querySelector('#order-search').oninput=e=>{search=e.target.value;renderResults();};}
function renderResults(){const list=orders.list().filter(o=>(filter==='all'||o.status===filter)&&`${o.id} ${o.name} ${o.model}`.toLowerCase().includes(search.toLowerCase().trim()));document.querySelector('#orders-results').innerHTML=list.length?list.map(item=>`<article class="order-card"><header><span>${t('订单编号','Order')} <strong>${esc(item.id)}</strong></span>${badge(item)}</header><div class="order-card-content"><a class="order-cover-link" href="${detailURL(item)}"><img src="${esc(item.cover)}" alt="${esc(item.name)}"></a><div class="order-card-info"><a href="${detailURL(item)}"><h2>${esc(item.name)}</h2></a><p>${esc(item.model)} · ${item.quantity} ${t('个手机壳','case(s)')}</p><div class="order-fulfillment-label">${fulfillmentTag(item)}</div><time datetime="${new Date(item.createdAt).toISOString()}">${t('创建时间','Created')} ${date(item.createdAt)}</time></div><div class="checkout-order-action"><strong>${amount(item)}</strong><a href="${detailURL(item)}">${t('订单详情','Order details')} ↗</a>${item.status==='paid'?`<a class="order-pay-link secondary" href="${detailURL(item)}">${t(item.fulfillment?.method==='delivery'?'查看收货地址':item.fulfillment?.method==='pickup'?'查看设备 / 导航':'查看领取信息',item.fulfillment?.method==='delivery'?'Delivery address':item.fulfillment?.method==='pickup'?'Printer & directions':'Fulfillment details')} ↗</a>`:''}${item.status==='pending'?`<a class="order-pay-link primary" href="./checkout.html?order=${encodeURIComponent(item.id)}">${t('去支付','Pay now')} →</a>`:''}</div></div></article>`).join(''):`<div class="checkout-empty"><h2>${t('暂无相关订单','No matching orders')}</h2><p>${t(search?'试试其他订单编号或作品名称。':'从喜欢的设计开始，创建你的打印订单。',search?'Try a different order number or design.':'Choose a design to create your print order.')}</p><a class="primary" href="./my-designs.html">${t('我的设计','My designs')} ↗</a></div>`;}
document.querySelector('#flow-language').onchange=e=>{lang=e.target.value;try{localStorage.setItem('popomo-language',lang);}catch{}render();};render();if(query.get('payment')==='success'&&order?.status==='paid'){paymentSuccess();const url=new URL(location.href);url.searchParams.delete('payment');history.replaceState(null,'',url);}

function paymentSuccess(){const dialog=document.createElement('dialog');dialog.className='payment-success-dialog';dialog.setAttribute('aria-labelledby','payment-success-title');dialog.innerHTML=`<span class="payment-success-icon" aria-hidden="true">✓</span><h2 id="payment-success-title">${t('支付成功','Payment successful')}</h2><p>${t('你的订单已支付，设计已保存。','Your payment is complete and your design is saved.')}</p><strong>${amount(order)}</strong><small>${t('订单编号','Order number')} ${esc(order.id)}</small><div><button class="primary" id="success-detail">${t('查看订单详情','View order details')}</button><a class="secondary" href="./checkout.html?view=orders">${t('我的订单','My orders')}</a></div>`;document.body.append(dialog);dialog.querySelector('button').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.showModal();}
function confirmPrinted(){if(order.status!=='paid'||order.fulfillment?.method!=='pickup')return;const dialog=document.createElement('dialog');dialog.className='printed-confirm-dialog';dialog.setAttribute('aria-labelledby','printed-confirm-title');dialog.innerHTML=`<h2 id="printed-confirm-title">${t('确认已完成打印？','Has printing finished?')}</h2><p>${t('确认后，订单将标记为已打印，并更新作品的打印次数。','This marks the order as printed and updates your design’s print count.')}</p><div><button class="tertiary" id="print-cancel">${t('取消','Cancel')}</button><button class="primary" id="print-confirm">${t('确认已打印','Confirm printed')}</button></div>`;document.body.append(dialog);dialog.querySelector('#print-cancel').onclick=()=>dialog.close();dialog.querySelector('#print-confirm').onclick=()=>{try{order=orders.printed(order.id);dialog.close();render();}catch{dialog.close();showError();}};dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.showModal();}
